package com.camstream.mobile;
import android.Manifest;import android.content.pm.PackageManager;import android.os.Bundle;import android.widget.*;import androidx.annotation.NonNull;import androidx.appcompat.app.AppCompatActivity;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.view.PreviewView;import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import com.google.common.util.concurrent.ListenableFuture;import java.util.concurrent.ExecutionException;
public class CameraActivity extends AppCompatActivity {
 PreviewView preview;int lens=CameraSelector.LENS_FACING_FRONT;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_camera);preview=findViewById(R.id.preview);findViewById(R.id.switchCamera).setOnClickListener(v->{lens=lens==CameraSelector.LENS_FACING_FRONT?CameraSelector.LENS_FACING_BACK:CameraSelector.LENS_FACING_FRONT;startCamera();});if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)startCamera();else ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.CAMERA},8);}
 void startCamera(){ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(this);future.addListener(()->{try{ProcessCameraProvider provider=future.get();provider.unbindAll();Preview p=new Preview.Builder().build();p.setSurfaceProvider(preview.getSurfaceProvider());CameraSelector selector=new CameraSelector.Builder().requireLensFacing(lens).build();provider.bindToLifecycle(this,selector,p);}catch(Exception e){Toast.makeText(this,"Camera is unavailable on this device.",Toast.LENGTH_LONG).show();}},ContextCompat.getMainExecutor(this));}
 @Override public void onRequestPermissionsResult(int r,@NonNull String[] p,@NonNull int[] g){super.onRequestPermissionsResult(r,p,g);if(r==8&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startCamera();else Toast.makeText(this,"Camera permission is required for preview.",Toast.LENGTH_LONG).show();}
}
